import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 7.8
.target sm_89
.address_size 64

.visible .entry conv2d_kernel(
    .param .u64 input_ptr,
    .param .u64 weight_ptr,
    .param .u64 bias_ptr,
    .param .u64 output_ptr,
    .param .s32 total_elements
)
{
    .reg .u32 %r<60>;
    .reg .u64 %rd<40>;
    .reg .f32 %f<10>;
    .reg .pred %p<15>;

    ld.param.u64 %rd1, [input_ptr];
    ld.param.u64 %rd2, [weight_ptr];
    ld.param.u64 %rd3, [bias_ptr];
    ld.param.u64 %rd4, [output_ptr];
    ld.param.s32 %r5, [total_elements];

    cvta.to.global.u64 %rd1, %rd1;
    cvta.to.global.u64 %rd2, %rd2;
    cvta.to.global.u64 %rd3, %rd3;
    cvta.to.global.u64 %rd4, %rd4;

    mov.u32 %r1, %ctaid.x;
    mov.u32 %r2, %ntid.x;
    mov.u32 %r3, %tid.x;
    mad.lo.s32 %r4, %r1, %r2, %r3;

    setp.ge.s32 %p1, %r4, %r5;
    @%p1 bra DONE;

    // decode idx -> n, oc, oh, ow
    mov.u32 %r10, 55;               // OW
    div.s32 %r11, %r4, %r10;        // tmp1 = idx / OW
    rem.s32 %r12, %r4, %r10;        // ow

    mov.u32 %r13, 55;               // OH
    div.s32 %r14, %r11, %r13;       // tmp2 = tmp1 / OH
    rem.s32 %r15, %r11, %r13;       // oh

    mov.u32 %r16, 96;               // OC
    div.s32 %r17, %r14, %r16;       // n
    rem.s32 %r18, %r14, %r16;       // oc

    // ih_base = oh*4 - 2 ; iw_base = ow*4 - 2
    mul.lo.s32 %r20, %r15, 4;
    sub.s32 %r20, %r20, 2;
    mul.lo.s32 %r21, %r12, 4;
    sub.s32 %r21, %r21, 2;

    // sum = bias[oc]
    mul.wide.s32 %rd10, %r18, 4;
    add.s64 %rd11, %rd3, %rd10;
    ld.global.f32 %f1, [%rd11];

    mov.u32 %r30, 0;               // ic
LOOP_IC:
    setp.ge.s32 %p2, %r30, 3;
    @%p2 bra END_IC;

    mov.u32 %r31, 0;               // kh
LOOP_KH:
    setp.ge.s32 %p3, %r31, 11;
    @%p3 bra END_KH;

    add.s32 %r32, %r20, %r31;      // ih
    setp.lt.s32 %p4, %r32, 0;
    setp.ge.s32 %p5, %r32, 224;
    or.pred %p6, %p4, %p5;
    @%p6 bra INC_KH;

    mov.u32 %r33, 0;               // kw
LOOP_KW:
    setp.ge.s32 %p7, %r33, 11;
    @%p7 bra END_KW;

    add.s32 %r34, %r21, %r33;      // iw
    setp.lt.s32 %p8, %r34, 0;
    setp.ge.s32 %p9, %r34, 224;
    or.pred %p10, %p8, %p9;
    @%p10 bra INC_KW;

    // input idx = ((n*3+ic)*224+ih)*224+iw
    mad.lo.s32 %r40, %r17, 3, %r30;
    mad.lo.s32 %r41, %r40, 224, %r32;
    mad.lo.s32 %r42, %r41, 224, %r34;
    mul.wide.s32 %rd20, %r42, 4;
    add.s64 %rd21, %rd1, %rd20;
    ld.global.f32 %f2, [%rd21];

    // weight idx = ((oc*3+ic)*11+kh)*11+kw
    mad.lo.s32 %r43, %r18, 3, %r30;
    mad.lo.s32 %r44, %r43, 11, %r31;
    mad.lo.s32 %r45, %r44, 11, %r33;
    mul.wide.s32 %rd22, %r45, 4;
    add.s64 %rd23, %rd2, %rd22;
    ld.global.f32 %f3, [%rd23];

    fma.rn.f32 %f1, %f2, %f3, %f1;

INC_KW:
    add.s32 %r33, %r33, 1;
    bra LOOP_KW;
END_KW:

INC_KH:
    add.s32 %r31, %r31, 1;
    bra LOOP_KH;
END_KH:

    add.s32 %r30, %r30, 1;
    bra LOOP_IC;
END_IC:

    // output idx = ((n*96+oc)*55+oh)*55+ow
    mad.lo.s32 %r50, %r17, 96, %r18;
    mad.lo.s32 %r51, %r50, 55, %r15;
    mad.lo.s32 %r52, %r51, 55, %r12;
    mul.wide.s32 %rd30, %r52, 4;
    add.s64 %rd31, %rd4, %rd30;
    st.global.f32 [%rd31], %f1;

DONE:
    ret;
