            "conv2d_kernel",
            grid=(grid, 1, 1),
            block=(block, 1, 1),
            arguments=[x, weight, bias, output, i32(total)],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return output

